def sort_numbers(numbers: str) -> str:
    # Mapping of number words to their integer values
    mapping = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Reverse mapping for converting back to words
    # {0: 'zero', 1: 'one', ...}
    reverse_mapping = {v: k for k, v in mapping.items()}

    # Functional pipeline:
    # 1. Split string into words
    # 2. Map words to integers
    # 3. Sort integers
    # 4. Map integers back to words
    # 5. Join words into a string
    return ' '.join(
        reverse_mapping[n] 
        for n in sorted(map(mapping.get, numbers.split()))
    )

# Test case
if __name__ == "__main__":
    print(sort_numbers('three one five')) 
    # Output: one three five
