from functools import reduce

def max_in_list(lst):
    if not lst:
        raise ValueError("max_in_list() arg is an empty sequence")
    return reduce(lambda a, b: a if a > b else b, lst)

Option 3: With a comparator-like approach (safe for empty by returning None)
from functools import reduce

def max_in_list(lst):
    if not lst:
        return None
    return reduce(lambda a, b: a if a > b else b, lst)

Usage:
